Lemma short_hdr_land1 : forall n, 0 <= n -> Z.land (2 * n) 1 = 0.
Proof.
  intros n Hn. change 1 with (Z.ones 1). rewrite Z.land_ones by lia. change (2^1) with 2. Z.div_mod_to_equations. lia.
Qed.

Lemma short_hdr_shr1 : forall n, 0 <= n -> Z.shiftr (2 * n) 1 = n.
Proof. intros n Hn. rewrite Z.shiftr_div_pow2 by lia. change (2^1) with 2. Z.div_mod_to_equations. lia. Qed.

Lemma short_hdr_range : forall n, 0 <= n <= 22 -> 0 <= 2 * n < 256.
Proof. lia. Qed.

(* [comment removed for export] *)
Lemma rw_cells_recut : forall m A cs cs',
  rw_cells rsegs m A cs -> cells_wf cs' -> cells_bytes cs' = cells_bytes cs -> rw_cells rsegs m A cs'.
Proof.
  intros m A cs cs' [[WF B] W] WF' E. split; [split; [exact WF'| rewrite E; exact B]|].
  rewrite <- (cells_bytes_length cs' WF'), E, (cells_bytes_length cs WF). exact W.
Qed.

Lemma firstn_app_skipn3 : forall {X} (l : list X) n k,
  (n + k <= length l)%nat -> firstn n l ++ firstn k (skipn n l) ++ skipn (n + k) l = l.
Proof.
  intros X l n k H.
  transitivity (firstn n l ++ skipn n l); [| apply firstn_skipn]. f_equal.
  rewrite Nat.add_comm, <- skipn_skipn. apply firstn_skipn.
Qed.

(* [comment removed for export] *)
Lemma rw_cells_cut1 : forall m A cs (n : nat),
  rw_cells rsegs m A cs -> (n + 1 <= cells_size cs)%nat ->
  rw_cells rsegs m A [CB n (firstn n (cells_bytes cs))] /\
  rw_cells rsegs m (A + Z.of_nat n) [CB 1 (firstn 1 (skipn n (cells_bytes cs))); CB (cells_size cs - n - 1) (skipn (n + 1) (cells_bytes cs))].
Proof.
  intros m A cs n H Hn.
  pose proof H as [[WF _] _]. pose proof (cells_bytes_length cs WF) as L.
  assert (R : rw_cells rsegs m A ([CB n (firstn n (cells_bytes cs))] ++
             [CB 1 (firstn 1 (skipn n (cells_bytes cs))); CB (cells_size cs - n - 1) (skipn (n + 1) (cells_bytes cs))])).
  { eapply rw_cells_recut; [exact H| |].
    - cbn. rewrite !firstn_length, !skipn_length. repeat split; lia.
    - cbn [cells_bytes cbytes app]. rewrite app_nil_r. apply firstn_app_skipn3. lia. }
  apply rw_cells_app in R. cbn [cells_size csize Nat.add] in R. rewrite Nat.add_0_r in R. exact R.
Qed.

Lemma rw_cells_uncut : forall m A n bs1 cs2,
  rw_cells rsegs m A [CB n bs1] -> rw_cells rsegs m (A + Z.of_nat n) cs2 -> rw_cells rsegs m A (CB n bs1 :: cs2).
Proof.
  intros m A n bs1 cs2 H1 H2. change (CB n bs1 :: cs2) with ([CB n bs1] ++ cs2). apply rw_cells_app.
  cbn [cells_size csize Nat.add]. rewrite Nat.add_0_r. split; assumption.
Qed.

(* [comment removed for export] *)
Definition short_w0 (bs b7 : list byte) : Z :=
  bv_unsigned (bv_extract 0 64 (le_bytes_to_word (b8 (2 * zlength bs) :: b7))).

Lemma short_cells_wordview : forall m a bs junk,
  rw_cells rsegs m a (short_cells bs junk) -> zlength bs <= 22 ->
  exists b7 rest, length b7 = 7%nat /\ rw_cells rsegs m a [CB 8 (b8 (2 * zlength bs) :: b7); CB 16 rest].
Proof.
  intros m a bs junk HS HL. pose proof HS as [[WF _] _]. unfold short_cells in WF. cbn in WF. unfold zlength in HL.
  set (tl := bs ++ [b8 0] ++ junk).
  assert (LT : length tl = 23%nat) by (subst tl; rewrite !length_app; cbn; lia).
  exists (firstn 7 tl), (skipn 7 tl). split; [rewrite firstn_length; lia|].
  eapply rw_cells_recut; [exact HS| |].
  - cbn. rewrite firstn_length, skipn_length. repeat split; lia.
  - subst tl. unfold short_cells. cbn [cells_bytes cbytes app]. rewrite !app_nil_r. f_equal. rewrite firstn_skipn. reflexivity.
Qed.

Lemma short_w0_val : forall bs b7, length b7 = 7%nat -> zlength bs <= 22 ->
  short_w0 bs b7 = 2 * zlength bs + 256 * le_val (map bv_unsigned b7) /\ 0 <= le_val (map bv_unsigned b7) < 2^56.
Proof.
  intros bs b7 L7 HL. unfold short_w0. rewrite load8_le_val by (cbn; lia). cbn [map le_val].
  pose proof (le_val_range (map bv_unsigned b7) (bytes_ok_map b7)) as R. rewrite length_map, L7 in R.
  change (256 ^ Z.of_nat 7) with (2^56) in R. unfold zlength in *. rewrite b8_unsigned by lia. lia.
Qed.

Lemma short_w0_land1 : forall bs b7, length b7 = 7%nat -> zlength bs <= 22 -> Z.land (short_w0 bs b7) 1 = 0.
Proof.
  intros bs b7 L7 HL. destruct (short_w0_val bs b7 L7 HL) as [-> R]. unfold zlength in *.
  change 1 with (Z.ones 1). rewrite Z.land_ones by lia. change (2^1) with 2. Z.div_mod_to_equations. lia.
Qed.
