Lemma short_w0_range : forall bs b7, length b7 = 7%nat -> zlength bs <= 22 -> 0 <= short_w0 bs b7 < 2^64.
Proof. intros bs b7 L7 HL. destruct (short_w0_val bs b7 L7 HL) as [-> R]. unfold zlength in *. lia. Qed.

Lemma land_255 : forall x, 0 <= x -> Z.land x 255 = x mod 256.
Proof. intros x Hx. change 255 with (Z.ones 8). rewrite Z.land_ones by lia. reflexivity. Qed.

Lemma short_w0_byte : forall bs b7, length b7 = 7%nat -> zlength bs <= 22 -> Z.land (short_w0 bs b7) 255 = 2 * zlength bs.
Proof.
  intros bs b7 L7 HL. destruct (short_w0_val bs b7 L7 HL) as [-> R]. unfold zlength in *.
  rewrite land_255 by lia. Z.div_mod_to_equations. lia.
Qed.

(* [comment removed for export] *)
Lemma short_cells_recut3 : forall m a bs junk (k : nat),
  rw_cells rsegs m a (short_cells bs junk) -> zlength bs <= 22 -> (k <= 23)%nat ->
