Lemma long_buf_recut2 : forall m A bs junk alloc (k : nat),
  rw_cells rsegs m A (long_buf bs junk alloc) -> zlength bs <= alloc - 1 -> (Z.of_nat k <= alloc) ->
  rw_cells rsegs m A [CB k (firstn k (bs ++ b8 0 :: junk)); CB (Z.to_nat alloc - k) (skipn k (bs ++ b8 0 :: junk))].
Proof.
  intros m A bs junk alloc k HB HL Hk. pose proof HB as [[WF _] _]. unfold long_buf in WF. cbn in WF. unfold zlength in HL.
  eapply rw_cells_recut; [exact HB| |].
  - cbn. rewrite firstn_length, skipn_length, length_app. cbn [length]. repeat split; lia.
  - unfold long_buf. cbn [cells_bytes cbytes app]. rewrite !app_nil_r. rewrite firstn_skipn. reflexivity.
Qed.

