  rw_cells rsegs m (A + n) [C1 (b8 0); CB (Z.to_nat (alloc - n - 1)) rest] ->
  0 <= n <= alloc - 1 -> length bs = Z.to_nat n ->
  In (p, A, alloc) LB -> rblock_range A alloc -> alloc mod 2 = 0 -> 24 <= alloc -> alloc < 2^63 ->
