Lemma rw_cells_bytes_prefix : forall m A n bs cs,
  rw_cells rsegs m A (CB n bs :: cs) -> bytes_at rsegs m A bs.
Proof.
  intros m A n bs cs [[WF B] _]. cbn [cells_bytes cbytes] in B. apply bytes_at_app in B. destruct B as [B _]. exact B.
Qed.

Lemma bytes_at_sub : forall m A bs (k j : nat),
  bytes_at rsegs m A bs -> (k + j <= length bs)%nat -> bytes_at rsegs m (A + Z.of_nat k) (firstn j (skipn k bs)).
Proof.
  intros m A bs k j B H.
  rewrite <- (firstn_skipn k bs) in B. apply bytes_at_app in B. destruct B as [_ B].
  rewrite firstn_length_le in B by lia.
  rewrite <- (firstn_skipn j (skipn k bs)) in B. apply bytes_at_app in B. destruct B as [B _]. exact B.
Qed.

Lemma StrObj_data_bytes : forall LB m a S, StrObj LB m a S -> bytes_at rsegs m (sdata a S) (sb S ++ [b8 0]).
Proof.
  intros LB m a [bs [[[p A] alloc]|]] H; cbn in *.
  - destruct H as (_ & _ & _ & _ & _ & _ & _ & _ & junk & BUF). unfold long_buf in BUF.
    destruct BUF as [[WF B] _]. cbn [cells_bytes cbytes] in B.
    change (bs ++ [b8 0] ++ junk ++ []) with (bs ++ ([b8 0] ++ (junk ++ []))) in B.
    rewrite app_assoc in B. apply bytes_at_app in B. destruct B as [B _]. exact B.
  - destruct H as (_ & junk & OBJ). unfold short_cells in OBJ.
    destruct OBJ as [[WF B] _]. cbn [cells_bytes cbytes] in B.
    apply bytes_at_app in B. destruct B as [_ B]. rewrite (app_assoc bs [b8 0]) in B.
    apply bytes_at_app in B. destruct B as [B _]. cbn [length Z.of_nat Pos.of_succ_nat] in B.
    exact B.
Qed.
